import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.Bbwa0s72.js";const m=JSON.parse('{"title":"Conformance language and classes","description":"","frontmatter":{},"headers":[],"relativePath":"spec/conformance.md","filePath":"spec/conformance.md"}'),n={name:"spec/conformance.md"};function i(s,e,c,d,l,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="conformance-language-and-classes" tabindex="-1">Conformance language and classes <a class="header-anchor" href="#conformance-language-and-classes" aria-label="Permalink to &quot;Conformance language and classes&quot;">​</a></h1><h2 id="requirement-keywords" tabindex="-1">Requirement keywords <a class="header-anchor" href="#requirement-keywords" aria-label="Permalink to &quot;Requirement keywords&quot;">​</a></h2><p>The key words <strong>MUST</strong>, <strong>MUST NOT</strong>, <strong>REQUIRED</strong>, <strong>SHALL</strong>, <strong>SHALL NOT</strong>, <strong>SHOULD</strong>, <strong>SHOULD NOT</strong>, <strong>RECOMMENDED</strong>, <strong>MAY</strong>, and <strong>OPTIONAL</strong> in the Takoform specification are to be interpreted as described in <a href="https://www.rfc-editor.org/info/bcp14" target="_blank" rel="noreferrer">BCP 14</a> (<a href="https://www.rfc-editor.org/rfc/rfc2119" target="_blank" rel="noreferrer">RFC 2119</a>, <a href="https://www.rfc-editor.org/rfc/rfc8174" target="_blank" rel="noreferrer">RFC 8174</a>) when, and only when, they appear in all capitals.</p><p>Prose that does not use those keywords is explanatory. A normative JSON Schema is the structural minimum for its document, not the complete acceptance contract. Implementations MUST also enforce the BCP 14 semantic verifier rules in the owning Form Definition, Form Package, Interface, and trust sections; a schema-valid document can therefore still be non-conforming.</p><p>Where a prose statement and a normative schema directly disagree about the same structural condition, <strong>the schema wins</strong>. Semantic rules that the schema does not express add fail-closed requirements rather than contradicting it. Every schema this specification declares normative is listed in <a href="./schemas/"><code>schemas/</code></a>.</p><h2 id="conformance-classes" tabindex="-1">Conformance classes <a class="header-anchor" href="#conformance-classes" aria-label="Permalink to &quot;Conformance classes&quot;">​</a></h2><p>Takoform defines four independent roles. An implementation claims one or more of them, and a claim is only ever about the class it names: a conforming host does not become a conforming publisher by hosting Forms, and a conforming provider does not promote Form maturity.</p><h3 id="form-package-data" tabindex="-1">Form Package (data) <a class="header-anchor" href="#form-package-data" aria-label="Permalink to &quot;Form Package (data)&quot;">​</a></h3><p>A <strong>conforming Form Package</strong> MUST satisfy <a href="./form-package/"><code>form-package/</code></a> and <a href="./form-definition/"><code>form-definition/</code></a>: one definition, one exact <code>FormRef</code>, RFC 8785 canonical bytes, a closed file inventory, allowlisted data media types, and no executable, credential, placement, or commercial content. It MUST NOT depend on any host to be valid.</p><h3 id="form-host-protocol" tabindex="-1">Form host (protocol) <a class="header-anchor" href="#form-host-protocol" aria-label="Permalink to &quot;Form host (protocol)&quot;">​</a></h3><p>A <strong>conforming Form host</strong> MUST implement <a href="./host-api/"><code>host-api/</code></a>: versioned discovery, exact Form availability, reviewed preview and apply, optimistic concurrency, idempotent lifecycle, and the stable error taxonomy. It MUST reject a request whose exact Form identity it has not installed, and it MUST NOT return a Resource whose name, space, or Form identity differs from the one requested.</p><p>A conforming <strong>v1beta1 host</strong> (<a href="./host-api/v1beta1.html"><code>host-api/v1beta1.md</code></a>) additionally MUST: issue immutable UIDs and change them across delete/recreate; increment <code>generation</code> only on desired-spec change and <code>revision</code> on any representation change, serving the quoted revision as the strong ETag; reject stale generation and revision fences with <code>generation_conflict</code> and <code>revision_conflict</code>; fence a delete on the expected generation and never require the revision, which a client&#39;s own teardown moves; keep the package digest out of resource identity, queries, and fences; enforce role rules (no in-place revision update, <code>dependency_in_use</code> for bound targets); complete accepted mutations either synchronously or through resumable Operations; verify content-addressed artifact manifests blob-by-blob; publish Host Support Profiles free of price, SKU, region, and quota; serve a namespaced Form group as two ordinary path segments with no percent-encoded slash anywhere in a path; answer an operation or upload handle presented by any other tenant or principal with the surface&#39;s ordinary not-found outcome rather than a forbidden one; and answer a manifest or blob read only for a caller whose tenant already holds that content address (<a href="./decisions/0018-the-host-api-is-deployable-behind-ordinary-infrastructure.html">decision 0018</a>).</p><p>A conforming <strong>exact Interface implementation</strong> (<a href="./interface-contract/"><code>interface-contract/</code></a>) MUST satisfy each operation&#39;s input/output schemas, the closed error vocabulary, the declared consistency and pagination semantics, and every deterministic behavior fixture of the exact Interface Definition it claims.</p><p>When desired state contains a portable Connection, the host MUST resolve its <code>Kind/name</code> only within the source Resource&#39;s exact <code>metadata.space</code>. Cross-Space selection is not part of the portable Connection shape, and a host MUST NOT substitute a target from another Space. A target absent from the source Space fails apply as <code>resource_not_found</code> / HTTP 404 before mutation, even if the same identity exists in another Space or preview previously returned a plan.</p><p>Host Support evidence MUST execute every <code>desired</code>-stage negative fixture from the exact package bytes. It does not claim <code>observed</code>-stage coverage: portable HTTP has no operation that injects a fabricated observation into an otherwise conforming host.</p><p>Every Experimental or Stable Form MUST declare at least one <code>desired</code>-stage negative fixture. Host Support and provider compatibility evidence therefore both have a non-empty negative-fixture set to execute.</p><p>A host <strong>MAY</strong> additionally implement the optional read-only interface declaration surface (<a href="./interface-declaration/"><code>interface-declaration/</code></a>). A host that does not is still fully conforming.</p><p>A host decides placement, capacity, credentials, and commercial terms. Those decisions are outside this specification, and a host MUST NOT require them to appear in portable desired state.</p><h3 id="form-provider-client" tabindex="-1">Form provider (client) <a class="header-anchor" href="#form-provider-client" aria-label="Permalink to &quot;Form provider (client)&quot;">​</a></h3><p>A <strong>conforming provider</strong> MUST send only declared desired state and MUST NOT place a credential, price, target, or backend selection in its state. On the retained v1alpha1 and v1alpha2 lanes it MUST carry the exact five-field installed Form identity on every mutation; on the v1beta1 lane it carries the exact four-field FormRef, with the package digest as optional audit evidence that never enters resource identity, queries, or fences (<a href="./decisions/0011-resource-identity-generation-and-revision.html">decision 0011</a>).</p><p>Provider compatibility evidence MUST execute every <code>desired</code>-stage negative and every <code>observed</code>-stage negative, rejecting the latter before host-produced status enters provider state. When the runner defines no semantics for a fixture stage, its presence fails the compatibility claim closed instead of being counted as executed evidence.</p><h3 id="form-publisher-distribution" tabindex="-1">Form publisher (distribution) <a class="header-anchor" href="#form-publisher-distribution" aria-label="Permalink to &quot;Form publisher (distribution)&quot;">​</a></h3><p>A <strong>conforming publisher</strong> MUST satisfy <a href="./trust/"><code>trust/</code></a>: immutable release bytes, exact digests, provenance, and an append-only revocation chain. A publisher MUST NOT overwrite or re-sign a released version in place.</p><h2 id="what-conformance-is-not" tabindex="-1">What conformance is not <a class="header-anchor" href="#what-conformance-is-not" aria-label="Permalink to &quot;What conformance is not&quot;">​</a></h2><p>Passing the package/schema checks proves the local data contract. Passing the portable host runner self-test additionally proves that the checked-in black-box runner can detect the lifecycle failures in its pinned matrix over HTTP; it proves only the disposable reference host used by that test.</p><p>Neither result is, or may be presented as, evidence of publication, external Host Support, production activation, Form maturity, revocation enforcement, or interoperability with a particular host. Those require evidence from the party that actually performed the external operation. The maturity requirements are owned by <a href="./project-lifecycle.html"><code>project-lifecycle.md</code></a>.</p>',26)])])}const f=t(n,[["render",i]]);export{m as __pageData,f as default};
